      "causa_raiz": "O tempo de renderização na GPU atingiu 28.27ms (com 69 violações de orçamento), excedendo substancialmente o teto de 16.67ms para sustentação de 60 FPS. Embora o número de Draw Calls (964) esteja dentro do orçamento máximo de 2579, a GPU GTX 1650 está sobrecarregada por complexidade de sombreamento (fillrate/shading), provavelmente devido a shaders pesados, sobreposição excessiva de transparência (overdraw), resolução nativa sem escalonamento dinâmico ou configurações de pós-processamento desreguladas.",
      "codigo_refatorado": "using UnityEngine;
using UnityEngine.Rendering;

public class ScalableGraphicsManager : MonoBehaviour
{
    [Header("Qualidade Dinâmica")]
    [SerializeField] private float targetFrameBudgetMs = 16.67f;
    [SerializeField] private float minDynamicResolutionScale = 0.70f;
    [SerializeField] private float maxDynamicResolutionScale = 1.0f;

    private float currentScale = 1.0f;

    private void Awake()
    {
        // Desativa recursos desnecessários para GPU em hardware modesto
        QualitySettings.shadowCascades = 2;
        QualitySettings.shadowDistance = 40f;
        QualitySettings.antiAliasing = 0;
    }

    private void Update()
    {
        // Monitora o frame time e ajusta resolução dinamicamente para preservar o limite de GPU
        float lastFrameMs = Time.unscaledDeltaTime * 1000f;
        if (lastFrameMs > targetFrameBudgetMs)
        {
            currentScale = Mathf.Max(minDynamicResolutionScale, currentScale - 0.05f);
        }
        else if (lastFrameMs < targetFrameBudgetMs * 0.85f)
        {
            currentScale = Mathf.Min(maxDynamicResolutionScale, currentScale + 0.02f);
        }

        ScalableBufferManager.ResizeBuffers(currentScale, currentScale);
    }
}",
      "explicacao_didatica": "A placa de vídeo (GPU) está demorando 28 milissegundos para desenhar a imagem inteira na tela, o que impede que o jogo rode a 60 quadros por segundo (onde cada quadro precisa ficar pronto em até 16.6ms). O script ajusta dinamicamente a resolução interna da imagem do jogo e limita o alcance das sombras quando percebe que a GPU está demorando muito. Isso reduz a quantidade de pixels calculados por segundo, aliviando a placa sem precisar cortar objetos do cenário."
    },
    {
      "tipo": "GC",
      "causa_raiz": "Foram registradas alocações de 96KB de lixo de memória gerando uma pausa de Garbage Collector de 5.60ms (gc_collect_ms: 5.60), o que rouba um terço do orçamento de frame da CPU (14.06ms) e causa engasgos perceptíveis (micro-stutter).",
      "codigo_refatorado": "using UnityEngine;

public class NonAllocCollisionSensor : MonoBehaviour
{
    [SerializeField] private LayerMask detectionMask;
    [SerializeField] private float detectionRadius = 5f;

    // Buffer reutilizável para evitar alocações constantes na memória gerenciada
    private readonly Collider[] hitBuffer = new Collider[16];

    private void Update()
    {
        int hitCount = Physics.OverlapSphereNonAlloc(transform.position, detectionRadius, hitBuffer, detectionMask);
        for (int i = 0; i < hitCount; i++)
        {
            ProcessTarget(hitBuffer[i]);
        }
    }

    private void ProcessTarget(Collider col)
    {
        // Lógica de processamento sem gerar strings ou instanciar objetos temporários
    }
}",
      "explicacao_didatica": "O coletor de lixo (GC) do Unity pausa o jogo para limpar objetos descartáveis da memória, e essa pausa durou 5.6ms neste quadro. O código corrigido utiliza métodos 'NonAlloc' com arrays fixos pré-alocados para checagens físicas ou listas reutilizáveis. Isso impede que novos blocos de memória sejam jogados fora a todo instante, acabando com os micro-congelamentos de tela."
    }
  ],
